        return 1;
    }

    // Поиск слова в файле
    string line;
    while (getline(file, line)) {
        size_t pos = 0;
        while ((pos = line.find(wordToSearch, pos)) != string::npos) {
            count++;
            pos += wordToSearch.length();
        }
    }

